 "content": "from collections import deque


def transform(grid):
    h, w = len(grid), len(grid[0])
    border = grid[0][0]
    # The repeated border-color run at the upper edge is the panel width.
    panel_w = 0
    while panel_w < w and grid[0][panel_w] == border:
        panel_w += 1
    separators = [r for r in range(h) if all(grid[r][c] == border for c in range(panel_w))]
    if len(separators) < 2:
        raise ValueError('panel separators not found')

    # Find each non-background, non-frame object on the right and retain its mask.
    seen = set()
    objects = []
    for r in range(h):
        for c in range(panel_w, w):
            color = grid[r][c]
            if color == 0 or color == border or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            cells = []
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    yy, xx = y + dy, x + dx
                    if (0 <= yy < h and panel_w <= xx < w and
                            (yy, xx) not in seen and grid[yy][xx] == color):
                        seen.add((yy, xx))
                        q.append((yy, xx))
            minr = min(y for y, x in cells); maxr = max(y for y, x in cells)
            minc = min(x for y, x in cells); maxc = max(x for y, x in cells)
            mask = tuple(tuple(grid[y][x] == color for x in range(minc, maxc + 1))
                         for y in range(minr, maxr + 1))
            objects.append((color, mask))

    out = [row[:panel_w] for row in grid]
    for top, bottom in zip(separators, separators[1:]):
        if bottom == top + 1:
            continue
        interior = [tuple(grid[r][c] == 0 for c in range(1, panel_w - 1))
                    for r in range(top + 1, bottom)]
        color = next((col for col, mask in objects if mask == tuple(interior)), None)
        if color is None:
            raise ValueError(f'no matching object for panel at row {top}: {interior}')
        for rr, rowmask in enumerate(interior, start=top + 1):
            for cc, is_hole in enumerate(rowmask, start=1):
                if is_hole:
                    out[rr][cc] = color
    return out
"
}

